-- HarborPOS PostgreSQL production schema v2.1
create extension if not exists pgcrypto;
create table if not exists businesses (id uuid primary key default gen_random_uuid(), name text not null, phone text, location text, address text, logo_text text, currency char(3) default 'KES', tax_rate numeric(6,4) default 0.16, receipt_footer text, receipt_paper text default '80mm', created_at timestamptz default now());
create table if not exists branches (id uuid primary key default gen_random_uuid(), business_id uuid not null references businesses(id) on delete cascade, name text not null, code text not null, location text, active boolean default true, created_at timestamptz default now(), unique(business_id,code));
create table if not exists access_levels (id int primary key, business_id uuid references businesses(id) on delete cascade, name text not null, features jsonb not null default '[]');
create table if not exists users (id uuid primary key default gen_random_uuid(), business_id uuid not null references businesses(id) on delete cascade, name text not null, email text not null unique, password_hash text not null, role text not null, level_id int references access_levels(id), active boolean default true, created_at timestamptz default now());
create table if not exists user_branches (user_id uuid references users(id) on delete cascade, branch_id uuid references branches(id) on delete cascade, primary key(user_id,branch_id));
create table if not exists feature_settings (id uuid primary key default gen_random_uuid(), business_id uuid not null references businesses(id) on delete cascade, feature_key text not null, settings jsonb not null default '{}', unique(business_id,feature_key));
create table if not exists customers (id uuid primary key default gen_random_uuid(), business_id uuid not null references businesses(id) on delete cascade, name text not null, phone text, email text, address text, credit_limit numeric(12,2) default 0, balance numeric(12,2) default 0, status text default 'active', created_at timestamptz default now());
create table if not exists suppliers (id uuid primary key default gen_random_uuid(), business_id uuid not null references businesses(id) on delete cascade, name text not null, phone text, email text, tax_pin text, address text, balance numeric(12,2) default 0, status text default 'active', created_at timestamptz default now());
create table if not exists products (id uuid primary key default gen_random_uuid(), business_id uuid not null references businesses(id) on delete cascade, branch_id uuid references branches(id), category text not null, name text not null, unit text default 'pcs', price numeric(12,2) not null, cost numeric(12,2) default 0, stock numeric(12,2) default 0, can_be_sold boolean default true, can_be_converted boolean default true, active boolean default true, created_at timestamptz default now());
create table if not exists stock_movements (id uuid primary key default gen_random_uuid(), branch_id uuid not null references branches(id), product_id uuid references products(id), movement_type text not null, quantity numeric(12,2) not null, reason text, reference_id text, created_at timestamptz default now());
create table if not exists stock_conversions (id uuid primary key default gen_random_uuid(), branch_id uuid not null references branches(id), from_product_id uuid references products(id), to_product_id uuid references products(id), input_qty numeric(12,2) not null, output_qty numeric(12,2) not null, reason text, created_at timestamptz default now());
create table if not exists rooms (id uuid primary key default gen_random_uuid(), branch_id uuid not null references branches(id) on delete cascade, room_no text not null, bedrooms int not null check (bedrooms between 1 and 3), room_type text not null, details text, nightly_rate numeric(12,2) not null, status text not null default 'available', created_at timestamptz default now(), unique(branch_id,room_no));
create table if not exists reservations (id uuid primary key default gen_random_uuid(), branch_id uuid not null references branches(id) on delete cascade, customer_id uuid references customers(id), guest_name text not null, guest_phone text, room_id uuid references rooms(id), check_in date not null, check_out date not null, adults int default 1, children int default 0, status text default 'confirmed', created_at timestamptz default now());
create table if not exists stays (id uuid primary key default gen_random_uuid(), branch_id uuid not null references branches(id) on delete cascade, reservation_id uuid references reservations(id), customer_id uuid references customers(id), guest_name text not null, guest_phone text, room_id uuid not null references rooms(id), check_in date not null, check_out date not null, nights int not null, room_total numeric(12,2) not null, deposit numeric(12,2) default 0, balance numeric(12,2) default 0, status text default 'checked-in', checked_in_at timestamptz default now(), checked_out_at timestamptz);
create table if not exists orders (id uuid primary key default gen_random_uuid(), branch_id uuid not null references branches(id) on delete cascade, cashier_user_id uuid references users(id), customer_id uuid references customers(id), order_no text not null, subtotal numeric(12,2) not null, tax numeric(12,2) not null default 0, total numeric(12,2) not null, payment_method text, payment_status text default 'pending', provider_reference text, note text, created_at timestamptz default now());
create table if not exists order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references orders(id) on delete cascade, product_id uuid references products(id), item_name text not null, qty numeric(12,2) not null, unit_price numeric(12,2) not null, line_total numeric(12,2) not null);
create table if not exists payments (id uuid primary key default gen_random_uuid(), branch_id uuid not null references branches(id), order_id uuid references orders(id), stay_id uuid references stays(id), method text not null, amount numeric(12,2) not null, status text not null, provider_reference text, provider text, paid_at timestamptz default now());
create table if not exists credit_sales (id uuid primary key default gen_random_uuid(), branch_id uuid not null references branches(id), customer_id uuid not null references customers(id), order_id uuid references orders(id), amount numeric(12,2) not null, due_date date not null, status text default 'open', created_at timestamptz default now());
create table if not exists credit_repayments (id uuid primary key default gen_random_uuid(), branch_id uuid not null references branches(id), customer_id uuid not null references customers(id), amount numeric(12,2) not null, method text not null, provider_reference text, note text, paid_date date not null default current_date, created_at timestamptz default now());
create table if not exists sms_inbox (id uuid primary key default gen_random_uuid(), business_id uuid not null references businesses(id) on delete cascade, sender text, recipient text, message_id text, message text not null, received_at timestamptz not null, tag text, parsed jsonb default '{}', unique(business_id,message_id));
create table if not exists mpesa_verification_rules (id uuid primary key default gen_random_uuid(), business_id uuid not null references businesses(id) on delete cascade, sender_name text default 'MPESA', amount_tolerance numeric(12,2) default 1, verification_window_minutes int default 30, webhook_url text, enabled boolean default true);
create table if not exists audit_logs (id uuid primary key default gen_random_uuid(), business_id uuid not null references businesses(id), branch_id uuid references branches(id), user_id uuid references users(id), action text not null, entity_type text, entity_id text, detail jsonb, created_at timestamptz default now());
create index if not exists idx_orders_branch_date on orders(branch_id, created_at desc);
create index if not exists idx_stays_branch_status on stays(branch_id, status);
create index if not exists idx_reservations_branch_dates on reservations(branch_id, check_in, check_out);
create index if not exists idx_customer_balance on customers(business_id, balance desc);
create index if not exists idx_credit_sales_customer on credit_sales(customer_id, status, due_date);
create index if not exists idx_sms_business_received on sms_inbox(business_id, received_at desc);
create index if not exists idx_audit_business_date on audit_logs(business_id, created_at desc);

create table if not exists business_state (business_id uuid primary key references businesses(id) on delete cascade, state jsonb not null default '{}', updated_at timestamptz default now());
create index if not exists idx_business_state_updated on business_state(updated_at desc);
